  politico_eco_bbs_comments_of_author_id        politico_eco_bbs_comments[]              @relation("politico_eco_bbs_comments_of_author_id")
  politico_eco_bbs_comments_of_last_editor_id   politico_eco_bbs_comments[]              @relation("politico_eco_bbs_comments_of_last_editor_id")
  politico_eco_bbs_comment_drafts               politico_eco_bbs_comment_drafts[]
  politico_eco_bbs_attachments                  politico_eco_bbs_attachments[]
  politico_eco_bbs_likes                        politico_eco_bbs_likes[]
  politico_eco_bbs_dislikes                     politico_eco_bbs_dislikes[]
  politico_eco_bbs_reports_of_reporting_user_id politico_eco_bbs_reports[]               @relation("politico_eco_bbs_reports_of_reporting_user_id")
  politico_eco_bbs_reports_of_target_user_id    politico_eco_bbs_reports[]               @relation("politico_eco_bbs_reports_of_target_user_id")
  politico_eco_bbs_blinds                       politico_eco_bbs_blinds[]
  politico_eco_bbs_warnings                     politico_eco_bbs_warnings[]
  politico_eco_bbs_escalations                  politico_eco_bbs_escalations[]
  politico_eco_bbs_auth_logs                    politico_eco_bbs_auth_logs[]
  politico_eco_bbs_access_logs                  politico_eco_bbs_access_logs[]
  politico_eco_bbs_error_logs                   politico_eco_bbs_error_logs[]
  politico_eco_bbs_user_activity_metrics        politico_eco_bbs_user_activity_metrics[]
  politico_eco_bbs_risk_events                  politico_eco_bbs_risk_events[]

  @@unique([email])
  @@index([created_at])
  @@index([last_login_at, role_status])
