  auditReference politico_eco_bbs_compliance_audits? @relation(fields: [audit_reference_id], references: [id], onDelete: Cascade)
  initiatorAdmin politico_eco_bbs_admins             @relation(fields: [initiator_admin_id], references: [id], onDelete: Cascade)

